from pathlib import Path
import os, hashlib, json
def manifest(root):
 out=[]
 for d,dirs,files in os.walk(root,followlinks=False):
  for n in sorted(dirs+files):
   p=Path(d)/n; rel=p.relative_to(root).as_posix()
   if p.is_symlink(): out.append((rel,'symlink',os.readlink(p)))
   elif p.is_dir(): out.append((rel,'dir'))
   else: out.append((rel,'file',p.stat().st_size,hashlib.sha256(p.read_bytes()).hexdigest()))
 return sorted(out)
